script:
// Gold Rush Tycoon v19 - progression route, laser doors, upgraders, weapon cabinets.
// Admin commands live in Menu -> Admin -> World (they also work in chat: /money 1000).
Game.on('join', function (name) { Game.toast(name + ' joined the Gold Rush!'); });

var WON = false;
Game.on('collect', function () {
  if (!WON && Game.money() >= 40000) { WON = true; Game.banner('GOLD TYCOON! You hit $40,000!'); }
});
Game.on('buy', function (label) {
  if (label === 'FREE Dropper') Game.toast('Ore rides the belt into your vault - step on the vault to sweep it.');
  if (label === 'Weapon Cabinets') Game.toast('Cabinets up by the right wall - buy a weapon once, re-equip it free forever.');
  if (label === 'Laser Doors') Game.toast('Laser doors ON - use the console inside your door to let people in.');
  if (label === 'Upgrader x1.5' || label === 'Upgrader x2') Game.toast('Ore through the arch is worth more now.');
  if (label === '2nd Floor + Stairs') Game.toast('Stairs are by the left wall.');
  if (label === 'MEGA Dropper') Game.banner('A MEGA DROPPER roars to life!');
  if (label === 'DIAMOND Dropper') Game.banner('DIAMOND DROPS! The mine sparkles.');
});
Game.on('zwave', function (n) { Game.toast(n + ' zombies rise in the plaza!'); });

var SPOTS = { ne: [100, -60], nw: [-100, -60], se: [100, 60], sw: [-100, 60], plaza: [0, 12] };
function plotId(p) { p = String(p || '').toLowerCase(); return p.indexOf('plot-') === 0 ? p : 'plot-' + p; }
function forMe(d) { return d && (d.to === 'all' || d.to === Game.myId()); }
function who(id) { return id === 'all' ? 'everyone' : (Game.playerName(id) || 'player'); }

// admin -> players messages: every receiver checks the sender really is an admin
Game.onNet('gm', function (d, from) { if (Game.isAdmin(from) && forMe(d)) { Game.addMoney(Math.max(-1e7, Math.min(1e7, +d.n || 0))); Game.toast('An admin sent you $' + d.n); } });
Game.onNet('gv', function (d, from) { if (Game.isAdmin(from) && forMe(d)) { Game.give(String(d.i)); Game.toast('An admin gave you ' + d.i); } });
Game.onNet('hl', function (d, from) { if (Game.isAdmin(from) && forMe(d)) Game.heal(9999); });
Game.onNet('br', function (d, from) { if (Game.isAdmin(from) && forMe(d) && d.to !== 'all') Game.tp(+d.x, +d.y, +d.z); });
Game.onNet('tm', function (d, from) { if (Game.isAdmin(from) && d) Game.setTime(+d.h); });

var P1 = { n: 'player', t: 'player', d: '', o: ['all'] };
var ITEMS = Game.items();

// ---------- Money ----------
Game.command({ id: 'money', cat: 'Money', label: 'Give money', desc: 'Add cash to a player (or everyone).',
  args: [{ n: 'amount', t: 'num', d: 1000, min: -1000000, max: 1000000 }, P1],
  quick: [['+$1k', { amount: 1000 }], ['+$10k', { amount: 10000 }], ['+$100k', { amount: 100000 }]],
  run: function (a) {
    var to = a.player || Game.myId();
    if (to === Game.myId()) { Game.addMoney(a.amount); return 'Added $' + a.amount + ' to you.'; }
    if (to === 'all') Game.addMoney(a.amount);
    Game.broadcast('gm', { to: to, n: a.amount }); return 'Sent $' + a.amount + ' to ' + who(to) + '.';
  } });
Game.command({ id: 'setmoney', cat: 'Money', label: 'Set my money', desc: 'Set your own cash to an exact amount.',
  args: [{ n: 'amount', t: 'num', d: 0, min: 0, max: 100000000 }],
  quick: [['$0', { amount: 0 }], ['$50k', { amount: 50000 }]],
  run: function (a) { Game.addMoney(a.amount - Game.money()); return 'Money set to $' + a.amount + '.'; } });

// ---------- Weapons ----------
Game.command({ id: 'give', cat: 'Weapons', label: 'Give item', desc: 'Hand a weapon, pet or apple to a player.',
  args: [{ n: 'item', t: 'pick', o: ITEMS, d: ITEMS[0] }, P1],
  run: function (a) {
    var to = a.player || Game.myId();
    if (to === Game.myId() || to === 'all') Game.give(a.item);
    if (to !== Game.myId()) Game.broadcast('gv', { to: to, i: a.item });
    return 'Gave ' + a.item + ' to ' + (to === Game.myId() ? 'you' : who(to)) + '.';
  } });
Game.command({ id: 'weapons', cat: 'Weapons', label: 'All weapons (me)', desc: 'Every weapon and the pet in your backpack.',
  run: function () { for (var i = 0; i < ITEMS.length; i++) if (ITEMS[i] !== 'golden-apple') Game.give(ITEMS[i]); return 'All weapons given.'; } });
Game.command({ id: 'weapon', cat: 'Weapons', label: 'Tune weapon damage', desc: 'Change a weapon\'s damage for this session (PvP = 1.5x).',
  args: [{ n: 'item', t: 'pick', o: ITEMS, d: ITEMS[0] }, { n: 'damage', t: 'num', d: 50, min: 1, max: 500 }],
  run: function (a) { Game.tuneItem(a.item, { damage: a.damage, pvp: Math.min(200, Math.round(a.damage * 1.5)) }); return a.item + ' now hits for ' + a.damage + '.'; } });
Game.command({ id: 'pet', cat: 'Weapons', label: 'Tune storm pet', desc: 'Pet guard radius, zap damage and zap range.',
  args: [{ n: 'radius', t: 'num', d: 30, min: 8, max: 60 }, { n: 'damage', t: 'num', d: 25, min: 1, max: 500 }, { n: 'zap', t: 'num', d: 14, min: 4, max: 30 }],
  run: function (a) { Game.tuneItem('storm-pet', { radius: a.radius, damage: a.damage, zapRange: a.zap }); return 'Storm pet tuned.'; } });

// ---------- Bases ----------
Game.command({ id: 'unlock', cat: 'Bases', label: 'Unlock all upgrades', desc: 'Buy every upgrade on a base for free (not the weapons).',
  args: [{ n: 'plot', t: 'plot' }],
  run: function (a) {
    var id = a.plot ? plotId(a.plot) : Game.myPlots()[0];
    if (!id || !Game.plotOwnerName(id)) return 'That base has no owner yet.';
    var bs = Game.buttons(id), k = 0;
    for (var j = 0; j < bs.length; j++) if (!bs[j].bought && !bs[j].give && Game.adminBuy(bs[j].id)) k++;
    return 'Unlocked ' + k + ' upgrades on ' + id + '.';
  } });
Game.command({ id: 'laser', cat: 'Bases', label: 'Laser doors on/off', desc: 'Switch any base\'s laser doors (they must be bought).',
  args: [{ n: 'plot', t: 'plot' }, { n: 'state', t: 'pick', o: ['off', 'on'], d: 'off' }],
  quick: [['All OFF', { plot: 'all', state: 'off' }], ['All ON', { plot: 'all', state: 'on' }]],
  run: function (a) {
    var ids = a.plot === 'all' ? Game.plotIds() : [plotId(a.plot)], on = a.state === 'on';
    for (var i = 0; i < ids.length; i++) Game.setToggle(ids[i] + '-laser', on);
    return 'Laser doors ' + (on ? 'ON' : 'OFF') + (a.plot === 'all' ? ' on every base.' : ' on ' + ids[0] + '.');
  } });
Game.command({ id: 'resetplot', cat: 'Bases', label: 'Free a base', desc: 'Kick the owner out and wipe that base back to empty.', danger: true,
  args: [{ n: 'plot', t: 'plot' }],
  run: function (a) { var id = plotId(a.plot); if (!Game.plotOwnerName(id)) return 'That base is already free.'; Game.resetPlot(id); return id + ' is free again.'; } });
Game.command({ id: 'owners', cat: 'Bases', label: 'Who owns what', desc: 'List every base and its owner.',
  run: function () {
    var ids = Game.plotIds(), out = [];
    for (var i = 0; i < ids.length; i++) out.push(ids[i].replace('plot-', '').toUpperCase() + ': ' + (Game.plotOwnerName(ids[i]) || 'free'));
    return out.join('  |  ');
  } });

// ---------- Players ----------
Game.command({ id: 'tp', cat: 'Players', label: 'Teleport me', desc: 'Jump to a base or the plaza.',
  args: [{ n: 'place', t: 'pick', o: ['plaza', 'ne', 'nw', 'se', 'sw'], d: 'plaza' }],
  quick: [['Plaza', { place: 'plaza' }], ['NE', { place: 'ne' }], ['NW', { place: 'nw' }], ['SE', { place: 'se' }], ['SW', { place: 'sw' }]],
  run: function (a) { var s = SPOTS[a.place]; if (!s) return 'Unknown place.'; Game.tp(s[0], 13, s[1]); } });
Game.command({ id: 'bring', cat: 'Players', label: 'Bring player', desc: 'Pull a player to where you are standing.',
  args: [{ n: 'player', t: 'player', d: '' }],
  run: function (a) {
    if (!a.player || a.player === Game.myId()) return 'Pick another player.';
    var me = Game.pos(); Game.broadcast('br', { to: a.player, x: me.x + 3, y: me.y, z: me.z }); return 'Bringing ' + who(a.player) + '.';
  } });
Game.command({ id: 'heal', cat: 'Players', label: 'Heal', desc: 'Full health for a player or everyone.',
  args: [P1], quick: [['Me', { player: 'me' }], ['Everyone', { player: 'all' }]],
  run: function (a) {
    var to = a.player === 'me' || !a.player ? Game.myId() : a.player;
    if (to === Game.myId() || to === 'all') Game.heal(9999);
    if (to !== Game.myId()) Game.broadcast('hl', { to: to });
    return 'Healed ' + (to === Game.myId() ? 'you' : who(to)) + '.';
  } });

// ---------- World ----------
Game.command({ id: 'zombies', cat: 'World', label: 'Zombie wave here', desc: 'Spawn zombies around you (max 8 at once).',
  args: [{ n: 'count', t: 'num', d: 4, min: 1, max: 8 }], quick: [['4', { count: 4 }], ['8', { count: 8 }]],
  run: function (a) { var me = Game.pos(); return 'Spawned ' + Game.zombies(a.count, me.x, me.z, 30) + ' zombies.'; } });
Game.command({ id: 'time', cat: 'World', label: 'Time of day', desc: 'Change the sky for everyone.',
  args: [{ n: 'hour', t: 'num', d: 12, min: 0, max: 24 }],
  quick: [['Day', { hour: 12 }], ['Sunset', { hour: 18.5 }], ['Night', { hour: 0 }]],
  run: function (a) { Game.setTime(a.hour); Game.broadcast('tm', { h: a.hour }); return 'Time set to ' + a.hour + ':00.'; } });
Game.command({ id: 'reset', cat: 'World', label: 'Reset every base', desc: 'All bases, buttons and lasers back to day one.', danger: true,
  run: function () { Game.resetWorld(); return 'The whole tycoon was reset.'; } });
